-- BlockDrive client installer for computers running the BlockOS desktop.
-- Generated by tools/build.py from src/blockdrive-installer.lua. Adds the BlockDrive app, the
-- BlockCloud client library and the bdrive command; no other desktop file is changed.
--   blockdrive-install [--yes]

local Version = "@VERSION@"
local Files = {}
--@FILES@

local Yes = ({ ... })[1] == "--yes"

local function WriteFile(Path, Content)
	local Dir = fs.getDir(Path)
	if (Dir ~= "" and not fs.exists(Dir)) then fs.makeDir(Dir) end
	local Handle = fs.open(Path, "w")
	if (not Handle) then error("Cannot write " .. Path, 0) end
	Handle.write(Content)
	Handle.close()
end

local function Ask(Question)
	if (Yes) then return true end
	while (true) do
		write(Question .. " (y/n) ")
		local Answer = (read() or ""):lower():sub(1, 1)
		if (Answer == "y") then return true end
		if (Answer == "n") then return false end
	end
end

term.setBackgroundColor(colors.black)
term.clear()
term.setCursorPos(1, 1)
if (term.isColor()) then term.setTextColor(colors.cyan) end
print("BlockDrive " .. Version .. " for BlockOS")
if (term.isColor()) then term.setTextColor(colors.white) end

if (fs.exists("/blockos/server/boot.lua")) then
	print("This computer runs BlockOS Server Edition, which already hosts BlockDrive. Install BlockDrive on the desktop computers that should use it.")
	return
end
if (not fs.exists("/blockos/sys/desktop.lua")) then
	print("BlockDrive needs the BlockOS desktop. Install BlockOS first:")
	print("wget run https://raw.githubusercontent.com/tamayaren/BlockOS/main/install.lua")
	return
end

local Installed = fs.exists("/blockos/apps/blockdrive/main.lua")
print(Installed and "BlockDrive is installed; this updates it." or "Adds BlockDrive (network storage in the Data Center) to this computer:")
print("  /blockos/apps/blockdrive  the app (Launchpad, Finder)")
print("  /blockos/lib/cloud        BlockCloud client library")
print("  /blockos/bin/bdrive.lua   the bdrive command")
print("Nothing else is changed, and BlockOS updates keep it.")
if (not Ask(Installed and "Update BlockDrive?" or "Install BlockDrive?")) then return end

local List = {}
for Path in pairs(Files) do table.insert(List, Path) end
table.sort(List)
for Index, Path in ipairs(List) do
	WriteFile(Path, Files[Path])
	if (Index % 6 == 0) then sleep(0) end
end
WriteFile("blockos/apps/blockdrive/version.txt", Version)
WriteFile("blockos/lib/cloud/version.txt", Version)

-- Pin it to the Dock on first install, the way bundled apps are.
local SettingsPath = "/blockos/data/settings.dat"
if (not Installed and fs.exists(SettingsPath)) then
	local Handle = fs.open(SettingsPath, "r")
	local Settings = textutils.unserialise(Handle.readAll() or "")
	Handle.close()
	if (type(Settings) == "table" and type(Settings.Dock) == "table") then
		local Pinned = false
		for _, ID in ipairs(Settings.Dock) do
			if (ID == "blockdrive") then Pinned = true end
		end
		if (not Pinned) then
			table.insert(Settings.Dock, math.max(1, #Settings.Dock), "blockdrive")
			WriteFile(SettingsPath, textutils.serialise(Settings))
		end
	end
end

print()
print("Done. Open BlockDrive from the Dock or Launchpad,")
print("choose Add Server, and approve this computer on the")
print("server console. In the terminal: bdrive help")
if (BlockOS and BlockOS.Desktop) then
	os.queueEvent("blockos_apps")
else
	print("Restart BlockOS (or this computer) to see it.")
end
